function proj(x,y){ // CSS: perspective * rotateY * rotateX applied to (x,y,0), origin at frame center
  let X=x, Y=y*Math.cos(rx), Z=y*Math.sin(rx);           // rotateX
  let X2=X*Math.cos(ry)+Z*Math.sin(ry), Z2=-X*Math.sin(ry)+Z*Math.cos(ry); // rotateY
