217	          const conversionData = [2.1, 2.8, 3.2, 2.9, 3.8, 4.2];
218	
219	          // Chart Dimensions
220	          const chartWidth = 1400;
221	          const chartHeight = 500;
222	          const startX = 100;
223	          const startY = 600;
224	          const barWidth = 80;
225	          const spacing = (chartWidth - barWidth * months.length) / (months.length + 1);
226	
227	          // Scales
228	          const maxRevenue = 25;
229	          const maxConversion = 5;
230	
231	          const getBarY = (val) => startY - (val / maxRevenue) * chartHeight;
232	          const getLineY = (val) => startY - (val / maxConversion) * chartHeight;
233	          const getX = (i) => startX + spacing + i * (barWidth + spacing) + barWidth / 2;
234	
235	          // Setup Elements
236	          const gridGroup = svg.querySelector(".gridlines");
237	          const xAxisGroup = svg.querySelector(".x-axis-labels");
238	          const barsGroup = svg.querySelector(".bars-group");
239	          const barLabelsGroup = svg.querySelector(".bar-labels-group");
240	          const lineLabelsGroup = svg.querySelector(".line-labels-group");
241	          const conversionPath = svg.querySelector(".conversion-path");
242	          const lineDot = svg.querySelector(".line-dot");
243	
244	          // Create Gridlines
245	          for (let i = 1; i <= 5; i++) {
246	            const y = startY - i * (chartHeight / 5);
247	            const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
248	            line.setAttribute("x1", startX);
249	            line.setAttribute("y1", y);
250	            line.setAttribute("x2", startX + chartWidth);
251	            line.setAttribute("y2", y);
252	            line.setAttribute("class", "grid-line");
253	            gridGroup.appendChild(line);
254	          }
255	
256	          // Create X-Axis Labels & Bars & Bar Labels
257	          const linePoints = [];
258	          months.forEach((month, i) => {
259	            const x = getX(i);
260	
261	            const label = document.createElementNS("http://www.w3.org/2000/svg", "text");
262	            label.setAttribute("x", x);
263	            label.setAttribute("y", startY + 30);
264	            label.setAttribute("class", "axis-label");
265	            label.textContent = month;
266	            xAxisGroup.appendChild(label);
267	
268	            const barHeight = (revenueData[i] / maxRevenue) * chartHeight;
269	            const bar = document.createElementNS("http://www.w3.org/2000/svg", "rect");
270	            bar.setAttribute("x", x - barWidth / 2);
271	            bar.setAttribute("y", startY);
272	            bar.setAttribute("width", barWidth);
273	            bar.setAttribute("height", 0);
274	            bar.setAttribute("class", "bar");
275	            barsGroup.appendChild(bar);
276	
277	            const barLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
278	            barLabel.setAttribute("x", x);
279	            barLabel.setAttribute("y", getBarY(revenueData[i]) - 10);
280	            barLabel.setAttribute("class", "bar-label");
281	            barLabel.textContent = `$${revenueData[i]}K`;
282	            barLabelsGroup.appendChild(barLabel);
283	
284	            linePoints.push(`${x},${getLineY(conversionData[i])}`);
285	
286	            const lineLabel = document.createElementNS("http://www.w3.org/2000/svg", "text");
287	            lineLabel.setAttribute("x", x);
288	            lineLabel.setAttribute("y", getLineY(conversionData[i]) - 15);
289	            lineLabel.setAttribute("class", "line-label");
290	            lineLabel.textContent = `${conversionData[i]}%`;
291	            lineLabelsGroup.appendChild(lineLabel);
292	          });
293	
294	          // Set Path Data
295	          conversionPath.setAttribute("d", `M ${linePoints.join(" L ")}`);
296	          const pathLength = conversionPath.getTotalLength();
