302	          tl.to(
303	            '[data-composition-id="data-chart"] .headline',
304	            {
305	              clipPath: "inset(0 0% 0 0)",
306	              duration: 1.2,
307	              ease: "power1.inOut",
308	            },
309	            0,
310	          );
311	
312	          tl.to(
313	            '[data-composition-id="data-chart"] .subtitle',
314	            {
315	              clipPath: "inset(0 0% 0 0)",
316	              duration: 1.2,
317	              ease: "power1.inOut",
318	            },
319	            0.2,
320	          );
321	
322	          tl.to(
323	            '[data-composition-id="data-chart"] .key',
324	            {
325	              opacity: 1,
326	              duration: 0.4,
327	              ease: "power2.out",
328	            },
329	            1.0,
330	          );
331	
332	          tl.to(
333	            '[data-composition-id="data-chart"] .grid-line',
334	            {
335	              opacity: 1,
336	              duration: 0.5,
337	              stagger: 0.25,
338	              ease: "power2.out",
339	            },
340	            0.5,
341	          );
342	
343	          // Bars
344	          const bars = barsGroup.querySelectorAll(".bar");
345	          const barLabels = barLabelsGroup.querySelectorAll(".bar-label");
346	
347	          bars.forEach((bar, i) => {
348	            const barHeight = (revenueData[i] / maxRevenue) * chartHeight;
349	            const startTime = 1.5 + i * 0.5;
350	
351	            tl.to(
352	              bar,
353	              {
354	                attr: { height: barHeight, y: startY - barHeight },
355	                duration: 0.8,
356	                ease: "power2.out",
357	              },
358	              startTime,
359	            );
360	
361	            tl.to(
362	              barLabels[i],
363	              {
364	                opacity: 1,
365	                duration: 0.3,
366	                ease: "power2.out",
367	              },
368	              startTime + 0.8,
369	            );
370	          });
371	
372	          // Line
373	          const lastBarStartTime = 1.5 + (months.length - 1) * 0.5;
374	          const lineStartTime = lastBarStartTime + 0.5;
375	
376	          tl.to(
377	            conversionPath,
378	            {
379	              strokeDashoffset: 0,
380	              duration: 3,
381	              ease: "none",
382	            },
383	            lineStartTime,
384	          );
385	
386	          // Line Dot & Labels
387	          tl.set(
388	            lineDot,
389	            {
390	              opacity: 1,
391	              attr: { cx: getX(0), cy: getLineY(conversionData[0]) },
392	            },
393	            lineStartTime,
394	          );
395	
396	          const lineLabels = lineLabelsGroup.querySelectorAll(".line-label");
397	          months.forEach((_, i) => {
398	            if (i > 0) {
399	              const x = getX(i);
400	              const y = getLineY(conversionData[i]);
401	              tl.to(
402	                lineDot,
403	                {
404	                  attr: { cx: x, cy: y },
405	                  duration: 3 / (months.length - 1),
406	                  ease: "none",
407	                },
408	                lineStartTime + ((i - 1) / (months.length - 1)) * 3,
409	              );
410	            }
411	
412	            const labelTime = lineStartTime + (i / (months.length - 1)) * 3 + 0.2;
413	
414	            lineLabels[i].textContent = "0.0%";
415	
416	            tl.to(
417	              lineLabels[i],
418	              {
419	                opacity: 1,
420	                duration: 0.1,
421	                ease: "power2.out",
422	              },
423	              labelTime,
424	            );
425	
426	            const dummy = { val: 0 };
427	            tl.to(
428	              dummy,
429	              {
430	                val: conversionData[i],
431	                duration: 0.8,
432	                ease: "power2.out",
433	                onUpdate: () => {
434	                  lineLabels[i].textContent = dummy.val.toFixed(1) + "%";
435	                },
436	              },
437	              labelTime,
438	            );
439	          });
440	
441	          // Source Line
442	          tl.to(
443	            '[data-composition-id="data-chart"] .source',
444	            {
445	              opacity: 1,
446	              duration: 0.5,
447	              ease: "power2.out",
448	            },
449	            ">+0.5",
450	          );
451	
452	          window.__timelines = window.__timelines || {};
453	          window.__timelines["data-chart"] = tl;
454	        })();
